function lag(level: StavebienWord["level"], rader: Rad[]): StavebienWord[] {
  return rader.map(([word, definition, sentence, origin, alternatives]) =>
    alternatives ? { word, level, definition, sentence, origin, alternatives } : { word, level, definition, sentence, origin },
  )
}

